function validate([nums]) {
  if (nums.length < 3 || nums.length > 1e5) return 'nums needs 3 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is an integer from 1 to 10^9.';
  let first = Infinity;
  let second = Infinity;
  for (const value of nums) {
    if (value <= first) first = value;
    else if (value <= second) second = value;
    else return null;
  }
  return 'nums must contain a strictly increasing triplet.';
}

