function maximumTripletValue(nums) {
  const n = nums.length;
  const rightMax = new Array(n + 1).fill(0);
  for (let k = n - 1; k >= 0; k--) {
    rightMax[k] = Math.max(rightMax[k + 1], nums[k]);
  }

  const sorted = [...new Set(nums)].sort((a, b) => a - b);
  const rank = new Map(sorted.map((value, index) => [value, index + 1]));
  const tree = new Array(sorted.length + 1).fill(0);
  const largestBelow = (r) => {
    let largest = 0;
    for (; r > 0; r -= r & -r) largest = Math.max(largest, tree[r]);
    return largest;
  };
  const insert = (r, value) => {
    for (; r < tree.length; r += r & -r) tree[r] = Math.max(tree[r], value);
  };

  let best = 0;
  for (let j = 0; j < n; j++) {
    const r = rank.get(nums[j]);
    const left = largestBelow(r - 1);
    const right = rightMax[j + 1];
    if (left > 0 && right > nums[j]) {
      best = Math.max(best, left - nums[j] + right);
    }
    insert(r, nums[j]);
  }
  return best;
}

