function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const hasTriplet = (nums) => {
    let first = Infinity;
    let second = Infinity;
    for (const value of nums) {
      if (value <= first) first = value;
      else if (value <= second) second = value;
      else return true;
    }
    return false;
  };
  for (;;) {
    const n = size === 'large' ? pick(1500, 2000) : pick(3, 9);
    const top = size === 'large' ? (rand() < 0.5 ? 1e9 : 3000) : pick(3, 12);
    const nums = Array.from({ length: n }, () => pick(1, top));
    if (hasTriplet(nums)) return [nums];
  }
}
